import{bQ as e,aL as a,u as r,G as o}from"./chunks/framework.C1gZXFVa.js";const n="/assets/020102.Cm-DmKMw.png",m=JSON.parse('{"title":"下单主流程","description":"平台限价单跨系统时序：用户经网关进委托，校验与预检后调撮合冻结建单并进簿；行情异步推送，不含撮合比价细节与初始化。","frontmatter":{"title":"下单主流程","description":"平台限价单跨系统时序：用户经网关进委托，校验与预检后调撮合冻结建单并进簿；行情异步推送，不含撮合比价细节与初始化。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/070502"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/070502"}],["meta",{"property":"og:title","content":"下单主流程 · TGEX"}],["meta",{"property":"og:description","content":"平台限价单跨系统时序：用户经网关进委托，校验与预检后调撮合冻结建单并进簿；行情异步推送，不含撮合比价细节与初始化。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"下单主流程 · TGEX"}],["meta",{"name":"twitter:description","content":"平台限价单跨系统时序：用户经网关进委托，校验与预检后调撮合冻结建单并进簿；行情异步推送，不含撮合比价细节与初始化。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"下单主流程\\",\\"description\\":\\"平台限价单跨系统时序：用户经网关进委托，校验与预检后调撮合冻结建单并进簿；行情异步推送，不含撮合比价细节与初始化。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/070502\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/070502\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/070502.md","filePath":"07.现货手册/05.核心流程/02.下单主流程.md"}'),p={name:"pages/070502.md"};function s(i,t,d,h,l,g){return a(),r("div",null,[...t[0]||(t[0]=[o('<div class="doc-eyebrow">现货手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="下单主流程" tabindex="-1">下单主流程 <a class="header-anchor" href="#下单主流程" aria-label="Permalink to &quot;下单主流程&quot;">​</a></h1><div class="doc-lead">平台限价单沿时序：用户 / 机器人 → 应用网关 → 委托系统 → 撮合系统；同步返回委托编号（已受理 ≠ 已全部成交）。深度与成交由撮合异步交给行情系统推送展示。</div><p align="center"><img src="'+n+'" alt="下单主流程时序"></p><p>本文假定服务已起来、交易对已可接单；以 <strong>平台撮合 · 限价单</strong> 为主路径。下文按上图时序展开。进簿之后的比价、挂剩见<a href="/pages/070508">撮合主流程</a>；展示侧见<a href="/pages/070509">行情推送流程</a>。</p><h2 id="_1-用户-机器人-→-应用网关" tabindex="-1">1. 用户 / 机器人 → 应用网关 <a class="header-anchor" href="#_1-用户-机器人-→-应用网关" aria-label="Permalink to &quot;1. 用户 / 机器人 → 应用网关&quot;">​</a></h2><p>调用方（App、开放 API、量化机器人等）提交限价单，经应用网关进入委托系统。</p><p>关键字段：买卖方向、交易对、价格、数量、来源；App 侧通常还要交易密码。</p><h2 id="_2-应用网关-→-委托系统" tabindex="-1">2. 应用网关 → 委托系统 <a class="header-anchor" href="#_2-应用网关-→-委托系统" aria-label="Permalink to &quot;2. 应用网关 → 委托系统&quot;">​</a></h2><p>网关只做转发与接入，不在本文展开鉴权细节。请求到达委托下单接口后，进入同步受理段。</p><h2 id="_3-委托-校验" tabindex="-1">3. 委托：校验 <a class="header-anchor" href="#_3-委托-校验" aria-label="Permalink to &quot;3. 委托：校验&quot;">​</a></h2><p>调撮合「下单」之前，委托侧先完成本地校验。任一步失败则走时序上的「拒单」支，<strong>经网关回调用方，不调撮合、不冻结</strong>：</p><ol><li>入参完整性（限价须有合法正价格与数量）</li><li>用户可交易状态（App 含交易密码；API / 机器人等按来源）</li><li>商户交易对：存在、启用、买卖开关、停盘时段</li><li>特殊业务限额（活动对等，按配置）</li><li>涨跌幅（平台撮合相对开盘价等）</li><li>精度截断与价量上下限</li><li>客户端订单号幂等（已存在则拒绝重复）</li></ol><p>第三方（非平台）撮合交易对另分支，不在本文主路径。</p><h2 id="_4-委托-→-撮合-余额预检" tabindex="-1">4. 委托 → 撮合：余额预检 <a class="header-anchor" href="#_4-委托-→-撮合-余额预检" aria-label="Permalink to &quot;4. 委托 → 撮合：余额预检&quot;">​</a></h2><p>校验通过后，委托向撮合读取币币钱包快照：买单看「价 × 量」计价币是否够，卖单看基础币是否够。</p><p><strong>只预检，不改可用 / 冻结。</strong> 预检失败同样拒单、不进入下一节「下单」。真正占用发生在调撮合「下单」成功之后。</p><h2 id="_5-委托-→-撮合-下单" tabindex="-1">5. 委托 → 撮合：下单 <a class="header-anchor" href="#_5-委托-→-撮合-下单" aria-label="Permalink to &quot;5. 委托 → 撮合：下单&quot;">​</a></h2><p>预检通过后，委托调用撮合下单。平台限价路径上，权威委托态与冻结收敛到撮合侧：一次调用覆盖冻结、建委托、触发进簿。</p><p>撮合侧在同步路径上完成：</p><ol><li><strong>可用 → 冻结</strong>，写委托热数据与 Redis 缓冲（买冻计价币 / 卖冻基础币）</li><li><strong>进入订单簿入口</strong>（比价、挂剩不在同步「已成交」语义里；细节见<a href="/pages/070508">撮合主流程</a>）</li></ol><p>钱包内如何减可用、加冻结见<a href="/pages/070802#total-to-frozen">用户币币账户缓存 · 增量：可用 → 冻结</a>。</p><p>撮合回委托：<strong>成功 + 委托编号</strong>。含义是冻结与建单已成功、已进入处理链，<strong>不等于已全部成交</strong>。</p><h2 id="_6-同步返回调用方" tabindex="-1">6. 同步返回调用方 <a class="header-anchor" href="#_6-同步返回调用方" aria-label="Permalink to &quot;6. 同步返回调用方&quot;">​</a></h2><p>委托经网关把结果回给用户 / 机器人：</p><table tabindex="0"><thead><tr><th>结果</th><th>含义</th></tr></thead><tbody><tr><td>成功 + 委托编号</td><td>已受理：资金已占用，委托已建立，已进入撮合处理链</td></tr><tr><td>校验 / 预检失败</td><td>未调撮合「下单」、未冻结</td></tr><tr><td>撮合拒绝 / 冻结失败</td><td>通常无冻结</td></tr><tr><td>调撮合超时</td><td><strong>可能已冻结</strong>：先按<a href="/pages/070510">委托查询主流程</a>确认终态，禁止未知时再发一笔新冻结</td></tr></tbody></table><p>状态与成交明细不在下单同步响应里带齐；资金教学表见<a href="/pages/0701#complete">业务概述 · 案例</a>。</p><h2 id="_7-异步旁路-撮合-→-行情-→-展示" tabindex="-1">7. 异步旁路：撮合 → 行情 → 展示 <a class="header-anchor" href="#_7-异步旁路-撮合-→-行情-→-展示" aria-label="Permalink to &quot;7. 异步旁路：撮合 → 行情 → 展示&quot;">​</a></h2><p>同步响应返回之后（或不阻塞同步等待），撮合将深度 / 成交等事件经消息队列交给行情系统。行情加工盘口、最新成交或 K 线，再按订阅推给客户端。</p><p>推送只服务展示，<strong>不改</strong>订单与资金的权威结果。断线后应先拉快照再接增量，见<a href="/pages/070509">行情推送流程</a>。</p><h2 id="本文边界" tabindex="-1">本文边界 <a class="header-anchor" href="#本文边界" aria-label="Permalink to &quot;本文边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对照</th><th>说明</th></tr></thead><tbody><tr><td><a href="/pages/070508">撮合主流程</a></td><td>进簿后比价、成交、外发意向</td></tr><tr><td><a href="/pages/070503">撤单主流程</a></td><td>撤销未完成委托</td></tr><tr><td><a href="/pages/070510">委托查询主流程</a></td><td>超时或列表查单；只读</td></tr><tr><td><a href="/pages/070509">行情推送流程</a></td><td>展示侧如何推深度与成交</td></tr><tr><td><a href="/pages/070512">手续费计费落地</a></td><td>成交时扣费；下单阶段通常只预占</td></tr><tr><td><a href="/pages/070504">委托 / 撮合初始化链路</a></td><td>启动准备；本文假定已可接单</td></tr><tr><td><a href="/pages/0701">业务概述</a></td><td>资金教学，不重复演算</td></tr></tbody></table><p>同组：<a href="/pages/070508">撮合主流程</a> · <a href="/pages/070503">撤单主流程</a> · <a href="/pages/070510">委托查询主流程</a> · <a href="/pages/070509">行情推送流程</a> · <a href="/pages/0701">业务概述</a> · <a href="/pages/070802">用户币币账户缓存</a></p>',33)])])}const _=e(p,[["render",s]]);export{m as __pageData,_ as default};
